const (
	KeyAppID    = "appId"
	KeyTopic    = "topic"
	KeyContract = "contract"
	KeyPubsub   = "pubsub"
	KeyPort     = "port"
	// KeyPortKind says how a single-port block reaches its port: PortKindBinding
	// (the default, also when the key is absent) through a Dapr binding, or
	// PortKindExternal through a client of its own (a database query, an HTTP
	// API), with no binding and no local folder.
	KeyPortKind = "portKind"
	KeyFromPort = "fromPort"
	KeyToPort   = "toPort"
	// KeyEndpoint carries a gateway's port in the system-host payload. It is
	// kept apart from port because the host resolves every port to a file
	// binding, and an endpoint is served over HTTP, not swept.
	KeyEndpoint = "endpoint"
	// KeyEndpointPath is the path a gateway's endpoint accepts items on, as its
	// scaffold record carries it; it rides with the endpoint in the payload as
	// path, where the system host and the ingress read it.
	KeyEndpointPath = "endpointPath"
// producer's channel during assembly. Its Pubsub stays empty until
// Model.UsePubsub names the system's.
type Component struct {
	AppID string    `json:"name"` // the Add<Kind> argument in the generated system class
	Kind  string    `json:"kind"` // a key of the blockParsers registry
	Topic *TopicKey `json:"-"`    // nil for kinds without a topic
	// Port is the single port of a topic block; empty for records that
	// predate it. Kept alongside Ports so the --output-json summary stays
	// additive-only.
	Port  string   `json:"port,omitempty"`
	Ports []string `json:"ports,omitempty"` // transactional blocks: exactly [from, to]
	// PortKind is template.PortKindExternal when the block reaches Port
	// through a client of its own, and empty for a binding port.
	PortKind string `json:"portKind,omitempty"`
	// Endpoint is the HTTP port a gateway exposes and EndpointPath the path
	// it accepts items on; both empty for every other kind. The endpoint
	// shares the port namespace but is never a file port.
	Endpoint     string `json:"endpoint,omitempty"`

